void Solver::bump_var(int var, double coeff) {
    // Update activity score
    activity[var] += var_inc * coeff;
    // Rescale activity scores and increment to prevent overflow
    if (activity[var] > 1e100) {
        for (int i = 1; i <= vars; i++) {
            activity[i] *= 1e-100;
        }
        var_inc *= 1e-100;
    }
    // Trigger heap update if variable is present
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}

